def P(x, y, z):
    return (x - y)**2 + (y - z)**2 + (z - x)**2

# Test cases for P(0, d, 2d)
d_values = [1, 2, 3, -1, -2]
results = {}
for d in d_values:
    value = P(0, d, 2 * d)
    results[d] = value
    print(f"P(0, {d}, {2*d}) = {value}")

# Check the expected form 6*d^2
for d in d_values:
    expected = 6 * d**2
    print(f"Expected 6*d^2 for d={d}: {expected}")
